<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Mockup — ChatEntry tool summary refactor</title>

<!-- 1. public libs, version pinned -->
<script src="https://cdn.tailwindcss.com/3.4.1"></script>
<script>
  // Design tokens exposed to Tailwind with the SAME names the real app uses
  // (DaisyUI semantic colors), so markup maps 1:1 to the Vue template.
  tailwind.config = {
    theme: {
      extend: {
        colors: {
          'base-100': '#0e0e11',
          'base-200': '#17171b',
          'base-300': '#26262c',
          'base-content': '#f4f4f5',
          primary: '#6366f1',
          'primary-lt': '#818cf8',
          info: '#3b82f6',
          success: '#10b981',
          warning: '#f59e0b',
          error: '#ef4444'
        }
      }
    }
  }
</script>

<style>
  :root {
    --bg:#0b0b0d; --surface:#16161a; --surface-2:#1f1f24; --surface-3:#26262c;
    --text:#f4f4f5; --dim:#a1a1aa; --muted:#71717a;
    --border:rgba(255,255,255,.08); --border-strong:rgba(255,255,255,.14);
    --primary:#6366f1; --info:#3b82f6; --ok:#10b981; --err:#ef4444;
    --font:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
    --mono:ui-monospace,"SF Mono",Menlo,Monaco,"Courier New",monospace;
    --fast:150ms; --base:220ms;
  }
  * { box-sizing: border-box; }
  html, body { height: 100%; }
  body {
    margin: 0; font-family: var(--font); background: var(--bg); color: var(--text);
    -webkit-font-smoothing: antialiased; font-size: 15px; line-height: 1.6;
  }
  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { transition: none !important; animation: none !important; }
  }
  :focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; border-radius: 4px; }

  /* ── DaisyUI-shaped primitives (hand-rolled so markup mirrors the real app) ── */
  .btn { display:inline-flex; align-items:center; justify-content:center; gap:.25rem;
    border-radius:6px; border:1px solid transparent; background:transparent; color:inherit;
    font:inherit; cursor:pointer; transition:background var(--fast) cubic-bezier(.4,0,.2,1), color var(--fast); }
  .btn-xs { height:1.35rem; padding:0 .4rem; font-size:.6875rem; line-height:1; }
  .btn-sm { height:1.75rem; padding:0 .6rem; font-size:.75rem; }
  .btn-ghost { color:var(--dim); }
  .btn-ghost:hover { background:rgba(255,255,255,.07); color:var(--text); }
  .btn-active { background:rgba(255,255,255,.1); color:var(--text); }
  .btn-primary { background:var(--primary); color:#fff; font-weight:500; }
  .btn-primary:hover { background:#5457e8; }
  .btn-disabled, .btn:disabled { opacity:.45; cursor:not-allowed; }
  .badge { display:inline-flex; align-items:center; gap:.25rem; border-radius:999px;
    padding:.1rem .45rem; font-size:.6875rem; font-weight:500; line-height:1.3; }
  .badge-xs { font-size:.625rem; padding:.05rem .4rem; }
  .badge-ghost { background:rgba(255,255,255,.07); color:var(--dim); }
  .badge-info { background:rgba(59,130,246,.18); color:#93c5fd; }
  .badge-success { background:rgba(16,185,129,.16); color:#6ee7b7; }
  .badge-error { background:rgba(239,68,68,.18); color:#fca5a5; }
  .loading { display:inline-block; width:.75rem; height:.75rem; border-radius:50%;
    border:2px solid rgba(255,255,255,.2); border-top-color:var(--info); animation:spin .7s linear infinite; }
  @keyframes spin { to { transform:rotate(360deg); } }
  .skeleton { background:linear-gradient(90deg, rgba(255,255,255,.05), rgba(255,255,255,.09), rgba(255,255,255,.05));
    background-size:200% 100%; border-radius:6px; animation:shimmer 1.4s ease-in-out infinite; }
  @keyframes shimmer { 0%{background-position:200% 0} 100%{background-position:-200% 0} }
  .tooltip { position:relative; }
  .tooltip:hover::after { content:attr(data-tip); position:absolute; left:50%; top:calc(100% + 6px);
    transform:translateX(-50%); background:#000; color:#fff; font-size:10px; padding:2px 6px;
    border-radius:4px; white-space:nowrap; z-index:300; pointer-events:none; }

  /* ── App shell ── */
  .shell { display:flex; height:100vh; overflow:hidden; }
  .sidebar { width:236px; flex:0 0 236px; border-right:1px solid var(--border);
    background:var(--surface); display:flex; flex-direction:column; }
  @media (max-width: 900px) { .sidebar { display:none; } }
  .main { flex:1; min-width:0; display:flex; flex-direction:column; background:var(--bg); }

  /* Mock control bar (chrome — not part of the design under review) */
  .mockbar { display:flex; flex-wrap:wrap; align-items:center; gap:6px;
    padding:6px 10px; border-bottom:1px dashed rgba(255,255,255,.12);
    background:repeating-linear-gradient(45deg,#101014,#101014 8px,#131318 8px,#131318 16px);
    font-size:11px; color:var(--muted); flex:0 0 auto; }
  .mockbar .seg { display:inline-flex; border:1px solid var(--border-strong); border-radius:6px; overflow:hidden; }
  .mockbar .seg button { border:0; background:transparent; color:var(--dim); font:inherit;
    padding:2px 8px; cursor:pointer; }
  .mockbar .seg button[aria-pressed="true"] { background:rgba(99,102,241,.25); color:#c7d2fe; }
  .mockbar .mbtn { border:1px solid var(--border-strong); background:transparent; color:var(--dim);
    font:inherit; padding:2px 8px; border-radius:6px; cursor:pointer; }
  .mockbar .mbtn:hover { background:rgba(255,255,255,.06); color:var(--text); }
  .mockbar .mbtn[disabled] { opacity:.4; cursor:not-allowed; }
  .mockbar .tag { font-family:var(--mono); font-size:10px; color:#a5b4fc;
    border:1px solid rgba(99,102,241,.4); border-radius:4px; padding:1px 5px; }

  /* ── Conversation ── */
  .feed { flex:1; overflow-y:auto; padding:16px 18px 120px; scroll-behavior:smooth; }
  .feed-inner { max-width:820px; margin:0 auto; transition:max-width var(--base); }
  .feed-inner.panel-narrow { max-width:375px; }

  /* The entry is the container every width-dependent rule queries */
  .entry { container-type:inline-size; container-name:entry; position:relative;
    border-radius:10px; padding:2px 0; }
  .entry + .entry { margin-top:2px; }
  .entry.is-channel { transition:background var(--fast); }
  .entry.is-channel:hover { background:rgba(244,244,245,.04); }

  /* Header — sticky in chat mode, transparent in channels (as today) */
  .entry-header { display:flex; align-items:center; gap:8px; flex-wrap:wrap;
    padding:0 4px 6px; font-size:12px; line-height:1; }
  .entry-header.is-sticky { position:sticky; top:0; z-index:20; margin-top:-4px;
    padding-top:6px; background:var(--bg); border-bottom:1px solid rgba(255,255,255,.10); }
  .entry > .entry-body { padding:0 4px; }
  .notion-content p { margin:0 0 .6em; color:rgba(244,244,245,.85); font-size:.9rem; }
  .notion-content p:last-child { margin-bottom:0; }
  .notion-content code { font-family:var(--mono); font-size:.8125rem;
    background:rgba(255,255,255,.07); padding:1px 4px; border-radius:4px; }

  /* ── NEW: one-line tool strip ─────────────────────────────────────────────
     Collapsed  → basic info about the tools executed (the LAST one + totals).
     Expanded   → becomes the header of the full details panel.
     It is the only new element in the entry; the header keeps its wrench. */
  .tool-strip {
    display:flex; align-items:center; gap:0; width:100%;
    margin:0 0 6px; border:1px solid var(--border); border-radius:8px;
    background:rgba(31,31,36,.55); overflow:hidden;
    transition:border-color var(--fast), background var(--fast);
  }
  .tool-strip:hover { border-color:rgba(255,255,255,.16); background:rgba(31,31,36,.85); }
  .tool-strip.is-open { border-color:rgba(99,102,241,.45); background:rgba(99,102,241,.08); }
  .tool-strip.is-error { border-color:rgba(239,68,68,.4); }
  .tool-strip.is-error .strip-name { color:#fca5a5; }

  .strip-main { display:flex; align-items:center; gap:8px; flex:1; min-width:0;
    border:0; background:transparent; color:inherit; font:inherit; cursor:pointer;
    padding:4px 8px; text-align:left; }
  .strip-icon { width:14px; display:flex; justify-content:center; flex:0 0 auto; font-size:.7rem; }
  .strip-name { font-family:var(--mono); font-size:.75rem; font-weight:600;
    color:rgba(244,244,245,.92); flex:0 0 auto; max-width:40%; overflow:hidden;
    text-overflow:ellipsis; white-space:nowrap; }
  .strip-arg { font-family:var(--mono); font-size:.6875rem; color:rgba(161,161,170,.75);
    flex:1 1 auto; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
  .strip-meta { font-size:.6875rem; color:var(--muted); font-variant-numeric:tabular-nums;
    flex:0 0 auto; white-space:nowrap; }
  .strip-meta .err { color:#fca5a5; }
  .strip-more { border:0; border-left:1px solid var(--border); background:transparent;
    color:var(--dim); cursor:pointer; padding:0 8px; align-self:stretch; font-size:.7rem; }
  .strip-more:hover { background:rgba(255,255,255,.07); color:var(--text); }
  .strip-caret { font-size:.6rem; color:var(--muted); flex:0 0 auto; padding-right:8px;
    transition:transform var(--fast); }
  .tool-strip.is-open .strip-caret { transform:rotate(180deg); }
  .strip-more + .strip-caret { padding-left:0; }

  /* Container queries: the strip degrades exactly like the real @lg/panel rules */
  @container entry (max-width: 520px) {
    .strip-group { display:none; }
    .strip-name { max-width:55%; }
    .hdr-wide-only { display:none !important; }
  }
  @container entry (max-width: 360px) {
    .strip-arg { display:none; }
  }

  /* ── Full details panel (the existing ChatMessageEvents wall) ── */
  .tool-panel { position:sticky; top:33px; z-index:10; display:flex; flex-direction:column;
    max-height:56vh; margin-bottom:8px; border:1px solid rgba(38,38,44,.9);
    border-radius:10px; background:var(--surface); box-shadow:0 8px 24px rgba(0,0,0,.45);
    overflow:hidden; }
  .tool-row { border-left:2px solid rgba(255,255,255,.15); padding:6px 10px;
    transition:background var(--fast); }
  .tool-row:hover { background:rgba(255,255,255,.04); }
  .tool-row.s-running { border-left-color:rgba(59,130,246,.6); }
  .tool-row.s-done { border-left-color:rgba(16,185,129,.5); }
  .tool-row.s-error { border-left-color:rgba(239,68,68,.7); }
  .args-grid { display:grid; grid-template-columns:minmax(4.5rem,7rem) 1fr;
    gap:1px 12px; margin:4px 0 0 26px; align-items:baseline; }
  .args-grid dt { font-size:.625rem; text-transform:uppercase; letter-spacing:.04em;
    color:var(--muted); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
  .args-grid dd { margin:0; font-family:var(--mono); font-size:.6875rem;
    color:rgba(161,161,170,.9); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
  .code-block { font-family:var(--mono); font-size:.6875rem; line-height:1.45;
    background:rgba(38,38,44,.5); border-radius:6px; padding:6px 8px; margin:0;
    max-height:10rem; overflow:auto; white-space:pre-wrap; word-break:break-all;
    color:rgba(244,244,245,.7); }

  /* ⋯ menu */
  .menu-wrap { position:relative; }
  .menu { position:absolute; right:0; top:calc(100% + 4px); min-width:11rem; z-index:200;
    display:none; padding:4px; border-radius:10px; background:var(--surface-2);
    border:1px solid var(--border-strong); box-shadow:0 12px 32px rgba(0,0,0,.5); }
  .menu.is-open { display:block; }
  .menu button { display:flex; align-items:center; gap:8px; width:100%; border:0;
    background:transparent; color:var(--dim); font:inherit; font-size:.8125rem;
    text-align:left; padding:6px 8px; border-radius:6px; cursor:pointer; }
  .menu button:hover { background:rgba(255,255,255,.07); color:var(--text); }

  /* Drawer */
  .drawer-backdrop { position:fixed; inset:0; background:rgba(0,0,0,.55); z-index:400;
    backdrop-filter:blur(2px); }
  .drawer { position:fixed; top:0; right:0; bottom:0; width:min(460px,92vw); z-index:401;
    display:flex; flex-direction:column; background:var(--surface);
    border-left:1px solid var(--border-strong); box-shadow:-16px 0 40px rgba(0,0,0,.5); }

  .toast { position:fixed; left:50%; bottom:24px; transform:translateX(-50%); z-index:500;
    background:var(--surface-3); color:var(--text); border:1px solid var(--border-strong);
    border-radius:8px; padding:8px 14px; font-size:.8125rem; box-shadow:0 8px 24px rgba(0,0,0,.5); }
  .toast[data-kind="error"] { border-color:rgba(239,68,68,.5); color:#fca5a5; }
</style>
</head>
<body>

<!-- ============================================================= -->
<!-- 3. SHELL                                                       -->
<!-- ============================================================= -->
<div class="shell">
  <aside class="sidebar" aria-label="Chats">
    <div class="px-4 py-3 text-sm font-semibold border-b border-white/10 flex items-center gap-2">
      <span class="w-5 h-5 rounded-md bg-primary/25 text-primary grid place-items-center text-[10px]">cx</span>
      codx-junior
    </div>
    <nav class="p-2 text-[13px] space-y-0.5">
      <div class="px-2 py-2 rounded-lg bg-primary/15 text-primary-lt flex items-center gap-2">
        <span class="text-[10px]">#</span> chat-entry-refactor
      </div>
      <div class="px-2 py-2 rounded-lg text-base-content/60 flex items-center gap-2">
        <span class="text-[10px]">#</span> design-system
      </div>
      <div class="px-2 py-2 rounded-lg text-base-content/60 flex items-center gap-2">
        <span class="text-[10px]">#</span> release-notes
      </div>
    </nav>
    <div class="mt-auto p-3 text-[11px] text-base-content/40 border-t border-white/10">
      MOCK: no backend, no auth
    </div>
  </aside>

  <main class="main">
    <!-- MOCK CONTROLS (chrome only) -->
    <div class="mockbar" role="region" aria-label="Mock controls">
      <span class="tag">mock</span>
      <div class="seg" role="group" aria-label="Panel width">
        <button type="button" data-act="width" data-width="wide" aria-pressed="true">Wide</button>
        <button type="button" data-act="width" data-width="narrow" aria-pressed="false">Narrow 375</button>
      </div>
      <button type="button" class="mbtn" data-act="channel" aria-pressed="false">Channel mode</button>
      <button type="button" class="mbtn" data-act="stream">▶ Stream a run</button>
      <span class="grow"></span>
      <button type="button" class="mbtn" data-act="load">Reload</button>
      <button type="button" class="mbtn" data-act="load-empty">Empty</button>
      <button type="button" class="mbtn" data-act="load-fail">Error</button>
      <button type="button" class="mbtn" data-act="reset">Reset mock</button>
    </div>

    <div class="feed" id="feed" aria-live="polite" aria-busy="false"></div>
  </main>
</div>

<div id="overlay"></div>

<script>
/* ═════════════════════════════════════════════════════════════════════
   A. MOCK DATA — mirrors the real Message shape (see ChatEntry.vue)
   ═════════════════════════════════════════════════════════════════════ */
const T0 = Date.parse('2024-05-02T10:00:00Z')
const iso = (s) => new Date(T0 + s * 1000).toISOString()

const ME = { username: 'ada', name: 'Ada Lovelace' }

const seedMessages = () => ([
  {
    doc_id: 'm_1', chat_id: 'c_dev', user: 'ada', role: 'user', done: true, hide: false,
    read_by: ['ada'], updated_at: iso(0), profiles: [], files: [], images: [], attachments: [],
    meta_data: { model: 'gpt-4o' }, tool_events: [], lifecycle_events: [],
    content: 'We need a `ChatEntry` refactor: show basic info about the tools executed — maybe just the last one — and keep the full details reachable from the header.'
  },
  {
    doc_id: 'm_2', chat_id: 'c_dev', user: 'codx-junior', role: 'assistant', done: true, hide: false,
    read_by: ['ada'], updated_at: iso(18), profiles: ['software_developer'], files: [], images: [], attachments: [],
    meta_data: { model: 'gpt-4o', time_taken: 7.4 }, tool_events: [], lifecycle_events: [],
    content: 'Agreed. A message that ran **no** tool must stay completely quiet — no strip, no empty panel. The strip only exists once something actually executed.'
  },
  {
    doc_id: 'm_3', chat_id: 'c_dev', user: 'codx-junior', role: 'assistant', done: true, hide: false,
    read_by: ['ada'], updated_at: iso(42), profiles: ['software_developer'], images: [], attachments: [],
    files: ['src/components/ChatEntry.vue'],
    meta_data: { model: 'gpt-4o', time_taken: 38.2 },
    content: 'Here is the plan for `ChatEntry.vue`.\n\nThe new **tool strip** sits directly under the header and carries the last execution plus the run totals. Clicking it expands the full wall; the header wrench toggles the exact same panel and stays reachable while a long message scrolls.',
    lifecycle_events: [{ run_id: 'run_9f2c1a', status: 'done', duration_ms: 3210 }],
    tool_events: [
      { tool_call_id: 'tc_1', tool: 'read_file', status: 'done', duration_ms: 180,
        request: { path: 'src/components/ChatEntry.vue' }, response: '312 lines' },
      { tool_call_id: 'tc_2', tool: 'grep', status: 'done', duration_ms: 240,
        request: { pattern: 'eventsOpen', glob: 'src/**/*.vue' }, response: '7 matches' },
      { tool_call_id: 'tc_3', tool: 'write_file', status: 'error', duration_ms: 90,
        request: { path: 'src/components/chat/ChatMessageEvents.vue' },
        error: 'EACCES: permission denied, open src/components/chat/ChatMessageEvents.vue' },
      { tool_call_id: 'tc_4', tool: 'read_file', status: 'done', duration_ms: 320,
        request: { path: 'src/components/chat/ChatMessageEvents.vue' }, response: '309 lines',
        output: '### ChatMessageEvents\n- renders the tool wall inside the sticky panel\n- owns the per-tool expand state' }
    ]
  },
  {
    doc_id: 'm_4', chat_id: 'c_dev', user: 'codx-junior', role: 'assistant', done: true, hide: false,
    read_by: [], updated_at: iso(61), profiles: [], images: [], attachments: [],
    meta_data: { model: 'gpt-4o', time_taken: 12.9 },
    lifecycle_events: [{ run_id: 'run_71ab', status: 'error', duration_ms: 1290 }],
    content: 'The test run failed — the failure belongs in the strip, not hidden behind a click.',
    tool_events: [
      { tool_call_id: 'tc_9', tool: 'read_file', status: 'done', duration_ms: 140,
        request: { path: 'package.json' }, response: '68 lines' },
      { tool_call_id: 'tc_10', tool: 'bash', status: 'error', duration_ms: 1150,
        request: { command: 'pnpm test --run' }, error: 'Command failed with exit code 1: 3 tests failed' }
    ]
  },
  {
    doc_id: 'm_5', chat_id: 'c_dev', user: 'codx-junior', role: 'assistant', done: false, hide: false,
    read_by: [], updated_at: iso(72), profiles: ['software_developer'], images: [], attachments: [],
    meta_data: { model: 'gpt-4o', cancellation_token_id: 'tok_abc' }, files: [],
    content: '', lifecycle_events: [{ run_id: 'run_live', status: 'running', duration_ms: null }],
    tool_events: [
      { tool_call_id: 'tc_20', tool: 'grep', status: 'running', duration_ms: null,
        request: { pattern: 'eventsOpen', glob: 'src/**/*.vue' } }
    ]
  }
])

const SEED_CHAT = { doc_id: 'c_dev', name: 'chat-entry-refactor', board: 'dev', project_id: 'codx-junior', mode: 'chat' }

/* ═════════════════════════════════════════════════════════════════════
   B. MOCK SERVER — every network call in the UI goes through mockFetch()
   ═════════════════════════════════════════════════════════════════════ */
const DB = { chat: { ...SEED_CHAT }, messages: seedMessages() }

const json = (data, status = 200) =>
  new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json' } })
const parseBody = (init) => { try { return JSON.parse(init.body || '{}') } catch { return {} } }
const findMessage = (id) => DB.messages.find(m => m.doc_id === id)

const routes = [
  {
    method: 'GET', path: /^\/api\/chats\/([^/]+)\/messages$/,
    handler: ({ searchParams }) => {
      if (searchParams.get('fail') === '1') return { __status: 500, error: 'server_error' }
      if (searchParams.get('empty') === '1') return []
      return DB.messages
    }
  },
  {
    method: 'POST', path: /^\/api\/chats\/([^/]+)\/messages\/([^/]+)\/tool-events$/,
    handler: ({ params, body }) => {
      const message = findMessage(params[1])
      if (!message) return { __status: 404, error: 'not_found' }
      const event = {
        tool_call_id: 'tc_' + Math.random().toString(36).slice(2, 8),
        tool: body.tool,
        status: body.status || 'running',
        request: body.request || {},
        duration_ms: body.duration_ms ?? null,
        ...(body.response ? { response: body.response } : {}),
        ...(body.error ? { error: body.error } : {}),
        ...(body.output ? { output: body.output } : {})
      }
      message.tool_events = [...(message.tool_events || []), event]
      return { __status: 201, message, event }
    }
  },
  {
    method: 'PATCH', path: /^\/api\/chats\/([^/]+)\/messages\/([^/]+)\/tool-events\/([^/]+)$/,
    handler: ({ params, body }) => {
      const message = findMessage(params[1])
      const event = message?.tool_events?.find(e => e.tool_call_id === params[2])
      if (!event) return { __status: 404, error: 'not_found' }
      Object.assign(event, body)
      return event
    }
  },
  {
    method: 'PATCH', path: /^\/api\/chats\/([^/]+)\/messages\/([^/]+)$/,
    handler: ({ params, body }) => {
      const message = findMessage(params[1])
      if (!message) return { __status: 404, error: 'not_found' }
      Object.assign(message, body)
      return message
    }
  },
  {
    method: 'DELETE', path: /^\/api\/chats\/([^/]+)\/messages\/([^/]+)$/,
    handler: ({ params }) => {
      const index = DB.messages.findIndex(m => m.doc_id === params[1])
      if (index < 0) return { __status: 404, error: 'not_found' }
      DB.messages.splice(index, 1)
      return { deleted: params[1] }
    }
  }
]

function mockFetch(input, init = {}) {
  const url = typeof input === 'string' ? input : input.url
  const method = (init.method || 'GET').toUpperCase()
  const { pathname, searchParams } = new URL(url, location.origin)
  const route = routes.find(r => r.method === method && r.path.test(pathname))

  return new Promise(resolve => setTimeout(() => {
    if (!route) return resolve(json({ error: 'not_found' }, 404))
    const params = pathname.match(route.path)?.slice(1) ?? []
    const result = route.handler({ params, searchParams, body: parseBody(init) })
    if (result && result.__status) {
      const { __status, ...payload } = result
      return resolve(json(payload, __status))
    }
    const status = method === 'POST' ? 201 : 200
    resolve(json(result, status))
  }, 90 + Math.random() * 160))
}

/* ═════════════════════════════════════════════════════════════════════
   C. STATE — single source of truth (serializable → localStorage)
   ═════════════════════════════════════════════════════════════════════ */
const STORAGE_KEY = 'mock.codx.chatEntry.state'

const defaultState = () => ({
  status: 'idle',              // idle | loading | error
  width: 'wide',               // wide | narrow   (container query)
  mode: 'chat',                // chat | channel
  messages: [],
  expanded: [],                // message ids with the full panel open
  openTools: [],               // tool_call_id with request/response open
  menu: null,                  // message id with the ⋯ menu open
  drawer: null,                // message id shown in the "Processing details" drawer
  streaming: false,
  toast: null
})

let state = defaultState()

const persist = () => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      width: state.width, mode: state.mode, messages: DB.messages,
      expanded: state.expanded, openTools: state.openTools
    }))
  } catch {}
}

const hydrate = () => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return false
    const saved = JSON.parse(raw)
    DB.messages = saved.messages || DB.messages
    state.width = saved.width || 'wide'
    state.mode = saved.mode || 'chat'
    state.expanded = saved.expanded || []
    state.openTools = saved.openTools || []
    return true
  } catch { return false }
}

/* ═════════════════════════════════════════════════════════════════════
   D. RENDER — pure function of state
   ═════════════════════════════════════════════════════════════════════ */
const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;')

const fmtMs = (ms) => ms == null ? '' : (ms < 1000 ? Math.round(ms) + ' ms' : (ms / 1000).toFixed(2) + ' s')
const fmtTime = (d) => { const x = new Date(d); return isNaN(x) ? '' : x.toISOString().slice(11, 16).replace('T', ' ') }
const isChannel = () => state.mode === 'channel'

function md(text) {
  if (!text) return ''
  return esc(text).split(/\n{2,}/).map(block => {
    const lines = block.split('\n')
    if (lines.every(l => /^-\s+/.test(l))) {
      return '<ul class="mb-2 pl-4 list-disc">' + lines
        .map(l => '<li>' + inline(l.replace(/^-\s+/, '')) + '</li>').join('') + '</ul>'
    }
    return '<p>' + inline(lines.join('<br>')) + '</p>'
  }).join('')
}
const inline = (t) => t
  .replace(/`([^`]+)`/g, '<code>$1</code>')
  .replace(/\*\*([^*]+)\*\*/g, '<strong class="text-base-content">$1</strong>')

/* ── Tool helpers ── */
const requestEntries = (event) => {
  const request = event?.request
  if (!request) return []
  let parsed = request
  if (typeof request === 'string') {
    try { parsed = JSON.parse(request) } catch { parsed = { input: request } }
  }
  return Object.entries(parsed || {})
}

const VALUE_KEYS = ['path', 'file', 'file_path', 'pattern', 'query', 'command', 'cmd', 'url']

// One-line argument preview: the most meaningful value of the request
function argPreview(event) {
  const entries = requestEntries(event)
  if (!entries.length) return ''
  const [key, value] = entries[0]
  const simple = value === null || ['string', 'number', 'boolean'].includes(typeof value)
  const text = simple ? String(value) : JSON.stringify(value)
  return VALUE_KEYS.includes(key) ? text : key + '=' + text
}

const runTotalMs = (message) => {
  const lifecycle = message.lifecycle_events || []
  const fromLifecycle = lifecycle.reduce((sum, e) => sum + (e.duration_ms || 0), 0)
  if (fromLifecycle) return fromLifecycle
  return (message.tool_events || []).reduce((sum, e) => sum + (e.duration_ms || 0), 0)
}

const statusIcon = (status, streaming) => {
  if (status === 'running' || (streaming && !status)) return '<span class="loading"></span>'
  if (status === 'error') return '<i class="fa-solid fa-circle-xmark" style="color:#ef4444"></i>'
  if (status === 'done') return '<i class="fa-solid fa-circle-check" style="color:#10b981"></i>'
  return '<i class="fa-solid fa-circle" style="color:#71717a"></i>'
}

const STATUS_WORD = { running: 'Running', done: 'Done', error: 'Failed' }

/* ── NEW: the one-line tool strip ──
   Collapsed: basic info about the tools executed → the LAST execution
   (status · tool · arg · duration) + run totals (count · time · errors).
   Expanded: same line, plus ⋯ (Processing details) on the right. */
function renderStrip(message) {
  const events = message.tool_events || []
  const last = events[events.length - 1] || null
  const streaming = !message.done
  const open = state.expanded.includes(message.doc_id)
  const errors = events.filter(e => e.status === 'error').length
  const status = last?.status || (streaming ? 'running' : 'done')
  const name = last?.tool || (streaming ? 'Starting…' : 'no tool')
  const arg = last ? argPreview(last) : ''
  const meta = []
  if (events.length) meta.push(events.length + (events.length === 1 ? ' tool' : ' tools'))
  if (runTotalMs(message)) meta.push(fmtMs(runTotalMs(message)))
  if (errors) meta.push('<span class="err">' + errors + ' error' + (errors > 1 ? 's' : '') + '</span>')

  const tip = last
    ? `${STATUS_WORD[last.status] || 'Unknown'} · ${last.tool}${last.duration_ms != null ? ' · ' + fmtMs(last.duration_ms) : ''}`
    : 'Waiting for the first tool'

  return `
  <div class="tool-strip ${open ? 'is-open' : ''} ${status === 'error' ? 'is-error' : ''} ${status === 'running' ? 'is-running' : ''}"
       role="group" aria-label="Tool activity">
    <button type="button" class="strip-main"
            data-act="toggle-panel" data-id="${message.doc_id}"
            data-key="strip-${message.doc_id}"
            aria-expanded="${open}" aria-controls="panel-${message.doc_id}"
            data-tip="${esc(tip)}">
      <span class="strip-icon">${statusIcon(status, streaming)}</span>
      <span class="strip-name" title="${esc(name)}">${esc(name)}</span>
      <span class="strip-arg" title="${esc(arg)}">${esc(arg)}</span>
      <span class="strip-meta">
        ${last?.duration_ms != null ? `<span class="hdr-wide-only" style="margin-right:6px">${fmtMs(last.duration_ms)}</span>` : ''}
        <span class="strip-group ${errors ? '' : 'opacity-60'}">${meta.join(' · ')}</span>
      </span>
    </button>
    ${open ? `<button type="button" class="strip-more tooltip" data-tip="Processing details"
                       data-act="drawer" data-id="${message.doc_id}"
                       aria-label="Open processing details">
                 <i class="fa-solid fa-ellipsis"></i>
               </button>` : ''}
    <span class="strip-caret" aria-hidden="true"><i class="fa-solid fa-chevron-down"></i></span>
  </div>`
}

/* ── Full details panel (today's <ChatMessageEvents>, header strip merged) ── */
function renderPanel(message) {
  const events = message.tool_events || []
  const lifecycle = message.lifecycle_events || []
  const rows = events.map((event, index) => {
    const open = state.openTools.includes(event.tool_call_id)
    const entries = requestEntries(event)
    const visible = entries.slice(0, 3)
    const hiddenCount = Math.max(entries.length - 3, 0)
    return `
    <div class="tool-row s-${event.status}">
      <button type="button" class="w-full flex items-center gap-2 text-left min-w-0"
              data-act="toggle-tool" data-tool="${event.tool_call_id}" data-key="tool-${event.tool_call_id}"
              aria-expanded="${open}" title="${STATUS_WORD[event.status] || 'Unknown'}">
        <span class="w-4 shrink-0 text-right text-[10px] tabular-nums text-base-content/30">${index + 1}</span>
        <span class="w-3.5 flex justify-center shrink-0">${statusIcon(event.status, false)}</span>
        <span class="font-mono text-xs font-semibold text-base-content truncate">${esc(event.tool)}</span>
        ${event.duration_ms != null ? `<span class="text-[10px] text-base-content/40 tabular-nums shrink-0">${fmtMs(event.duration_ms)}</span>` : ''}
        <span class="grow"></span>
        <span class="text-[10px] text-base-content/30 tabular-nums shrink-0">${entries.length} args</span>
        <i class="fa-solid fa-chevron-down text-[10px] text-base-content/40 shrink-0"
           style="transform:rotate(${open ? 180 : 0}deg);transition:transform 150ms"></i>
      </button>

      ${visible.length ? `<dl class="args-grid">
        ${visible.map(([key, value]) => {
          const text = (value === null || ['string', 'number', 'boolean'].includes(typeof value))
            ? String(value) : JSON.stringify(value)
          return `<dt title="${esc(key)}">${esc(key)}</dt>
                  <dd title="${esc(text)}">${esc(text)}</dd>`
        }).join('')}
      </dl>` : ''}
      ${hiddenCount ? `<p class="mt-0.5 ml-[26px] text-[10px] text-base-content/30">+${hiddenCount} more argument${hiddenCount > 1 ? 's' : ''}</p>` : ''}

      ${event.status === 'error' && event.error ? `
        <div class="mt-1 ml-[26px] flex items-start gap-1 text-[11px]" style="color:#fca5a5">
          <i class="fa-solid fa-triangle-exclamation text-[10px] mt-0.5 shrink-0"></i>
          <span class="line-clamp-2 break-all">${esc(event.error)}</span>
        </div>` : ''}

      ${open ? `
        <div class="mt-2 ml-[26px] space-y-2">
          ${entries.length ? `<div>
            <p class="text-[10px] uppercase tracking-wide text-base-content/40 mb-1">Arguments</p>
            <pre class="code-block">${esc(JSON.stringify(event.request, null, 2))}</pre>
          </div>` : ''}
          ${event.response ? `<div>
            <p class="text-[10px] uppercase tracking-wide text-base-content/40 mb-1">Result</p>
            <pre class="code-block">${esc(event.response)}</pre>
          </div>` : ''}
          ${event.output ? `<div>
            <p class="text-[10px] uppercase tracking-wide text-base-content/40 mb-1">Output</p>
            <div class="rounded-md border border-base-300/50 p-2 max-h-64 overflow-auto text-xs">${md(event.output)}</div>
          </div>` : ''}
        </div>` : ''}
    </div>`
  }).join('')

  const lifecycleRows = lifecycle.length ? `
    <ul class="divide-y divide-white/10 border-t border-white/10">
      ${lifecycle.map(e => `
        <li class="px-3 py-1.5 flex items-center gap-2 text-[11px]">
          <i class="fa-solid fa-circle-play text-[10px] shrink-0" style="color:#60a5fa"></i>
          <span class="font-mono text-base-content/50 truncate">${esc(String(e.run_id || '').slice(0, 8))}</span>
          <span class="badge badge-xs ${e.status === 'error' ? 'badge-error' : (e.status === 'done' ? 'badge-success' : 'badge-info')}">${esc(e.status)}</span>
          ${e.duration_ms != null ? `<span class="text-[10px] text-base-content/40 tabular-nums">${fmtMs(e.duration_ms)}</span>` : ''}
        </li>`).join('')}
    </ul>` : ''

  return `
  <div class="tool-panel" id="panel-${message.doc_id}" role="region"
       aria-label="Tools and events for this message">
    <div class="min-h-0 overflow-y-auto">
      ${rows ? `<div class="divide-y divide-white/10">${rows}</div>` : ''}
      ${lifecycleRows}
      ${!rows && !lifecycle.length ? '<div class="px-3 py-2 text-[11px] text-base-content/40">No events recorded for this message.</div>' : ''}
    </div>
  </div>`
}

/* ── One entry ── */
function renderEntry(message) {
